if(PHP_SAPI!=='cli')exit;$_SERVER['HTTP_HOST']='127.0.0.1:8799';$_SERVER['REQUEST_URI']='/';require __DIR__.'/site/wordpress/wp-load.php';wp_set_current_user(1);$out=['checked_at'=>gmdate('c'),'home'=>home_url('/'),'theme'=>get_stylesheet(),'wordpress'=>get_bloginfo('version'),'woocommerce'=>defined('WC_VERSION')?WC_VERSION:null,'products'=>[],'native_CMS_backend'=>true,'fictional_own_shop'=>true,'real_payment_provider'=>false,'email_disabled'=>true];foreach([15,18] as $id){$p=wc_get_product($id);$out['products'][]=['id'=>$id,'name'=>$p->get_name(),'type'=>$p->get_type(),'virtual'=>$p->is_virtual(),'price'=>$p->get_price(),'stock_management'=>$p->get_manage_stock(),'url'=>get_permalink($id)];}$front=get_post((int)get_option('page_on_front'));$out['front_page']=['id'=>$front->ID,'title'=>$front->post_title,'sha256'=>hash('sha256',$front->post_content)];echo wp_json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),"\n";
